	zip.Describe("POST /v1/evals/runs", zip.Doc{
		Description: "Runs a real evaluation and answers the summary when it is finished —\nthis is synchronous work, not a job id.\n\nFor each ACTIVE example in the dataset it calls the model under test, records a\ntrace, calls the LLM-as-judge, and records the judge's score with its\nreasoning. The answer carries the per-item results (item id, trace id, score,\noutput or error) alongside items, scored and avgScore.\n\nThe dataset must belong to the caller's org (404 otherwise) and must have at\nleast one ACTIVE example (422 otherwise).\n\nIt runs as YOU: the caller's own Authorization bearer drives the model gateway,\nso a request without one is 401 rather than a run made anonymously or under a\nservice identity. Only a non-reversible hash of that credential is recorded on\nthe traces.\n\nBounded and honest about it: an org may have at most 4 runs in flight and the\nfifth is 429 rather than queued, and the whole run is capped at 10 minutes —\nexamples past the deadline come back with an error instead of a score, and\nscored counts only real successes. A run where NOTHING scored answers 502, not\na 200 that looks like an evaluation. A run must be able to persist what it\nproduces, so a deployment with no datastore wired is 503 up front. Requires a\nvalidated principal; 403 without one.",
		Fields: map[string]string{
			"itemResult.error":      "Error is why this example produced no score — the model, the judge, or the\nrun's deadline. A result carrying one is not counted in Scored.",
			"itemResult.itemId":     "ItemID is the example that was scored.",
			"itemResult.output":     "Output is what the model under test answered, truncated at 2000 characters.",
			"itemResult.score":      "Score is the judge's grade.",
			"itemResult.traceId":    "TraceID is the model call this result came from.",
			"judgeSpec.criteria":    "Criteria is the standard the judge applies, defaulting to a correctness\ncriterion.",
			"judgeSpec.model":       "Model is the model that grades. It defaults to the model under test, so a\nrun with no judge named has the model grade itself.",
			"judgeSpec.name":        "Name is the score name the judge's grades are filed under, \"llm-judge\" by\ndefault. A name that is not a legal handle falls back to that default\nrather than being stored as sent.",
			"runRequest.dataset":    "Dataset is the set to score, which must belong to the caller's org and hold\nat least one ACTIVE example.",
			"runRequest.judge":      "Judge is the judge to grade with. Omitted, the model under test grades\nitself against a default correctness criterion under the score name\n\"llm-judge\".",
			"runRequest.limit":      "Limit caps how many examples this run scores. It defaults to 20, and\nanything above 100 falls back to that default.",
			"runRequest.model":      "Model is the model under test.",
			"runRequest.runName":    "RunName labels the run and is generated from the clock when omitted. It\nmust match ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$.",
			"runSummary.avgScore":   "AvgScore is the mean over the scored examples, 0 when none scored.",
			"runSummary.dataset":    "Dataset is the set that was scored.",
			"runSummary.items":      "Items is how many examples the run attempted.",
			"runSummary.judgeModel": "JudgeModel is the model that graded.",
			"runSummary.model":      "Model is the model under test.",
			"runSummary.results":    "Results is one row per attempted example.",
			"runSummary.runName":    "RunName is the run's label, which scores and traces are filed under.",
			"runSummary.scored":     "Scored is how many produced a real score. It counts successes only, so a\npartial run is honest about what it achieved.",
		},
	})
	zip.Describe("POST /v1/evals/scores", zip.Doc{
		Description: "Files one score event for the caller's org and answers 201 with it.\n\nThis is how human review and out-of-band graders land beside the automatic\nones: name the score, give it a value (or a stringValue for a categorical\nlabel), and attach it to a trace, a run, a dataset example, or any combination.\n\nScores are validated fail-closed. A value must be FINITE — NaN and Inf are 400\n— and if the org has declared a rubric for this name, that rubric decides the\ntype and the value must satisfy it: inside the numeric bounds, or one of the\nallowed categories. A caller cannot override the declared type by sending a\ndifferent dataType.\n\nA score is TELEMETRY, not metadata, so it needs the datastore: a deployment\nwith none wired answers 503 rather than accepting a score it cannot persist.\nRequires a validated principal; 403 without one, and the org is stamped from\nthe validated claim rather than read off the body.",
		Fields: map[string]string{
			"scoreReq.comment":       "Comment is the grader's reasoning, truncated at 2000 characters.",
			"scoreReq.dataType":      "DataType is NUMERIC, CATEGORICAL or BOOLEAN. A declared rubric overrides it\n— a caller cannot claim a type the org's rubric contradicts.",
			"scoreReq.datasetItemId": "ItemID attaches the score to one graded example.",
			"scoreReq.datasetName":   "Dataset attaches the score to one dataset.",
			"scoreReq.name":          "Name is the score name. A rubric of the same name, if the org has declared\none, decides this score's type and the values it may take.",
			"scoreReq.runName":       "RunName attaches the score to one run.",
			"scoreReq.stringValue":   "StringValue is the label of a CATEGORICAL score, which must be one the\nrubric allows.",
			"scoreReq.traceId":       "TraceID attaches the score to one model call.",
			"scoreReq.value":         "Value is the numeric score, which must be finite: NaN and Inf are refused.\nA BOOLEAN score takes 0 or 1.",
			"scoreView.comment":      "Comment is the grader's reasoning, truncated at 2000 characters.",
			"scoreView.dataType":     "DataType is NUMERIC, CATEGORICAL or BOOLEAN.",
			"scoreView.id":           "ID is the score event's handle.",
			"scoreView.name":         "Name is the score name, which a rubric of the same name governs.",
			"scoreView.runName":      "RunName is the run this score was recorded under, when it came from one.",
			"scoreView.stringValue":  "StringValue is the label of a CATEGORICAL score.",
			"scoreView.timestamp":    "Timestamp is when the score was recorded.",
			"scoreView.traceId":      "TraceID is the model call this score grades, when it grades one.",
			"scoreView.value":        "Value is the numeric score; for BOOLEAN it is 0 or 1.",
		},
	})
